package io.xeros.content.minigames.pest_control;
import io.xeros.content.instances.*;import io.xeros.content.minigames.SoloActivityRewards;
import io.xeros.content.combat.Hitmark;import io.xeros.content.combat.npc.*;
import io.xeros.model.Animation;import io.xeros.model.CombatType;import io.xeros.model.definitions.NpcDef;import io.xeros.model.entity.Entity;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.items.GameItem;import io.xeros.model.cycleevent.*;import java.util.*;
/** Private solo match: four portals, finite enemy waves, knight defense, no queue. */
public final class SoloPest extends InstancedArea {
 public static final Position EXIT=new Position(2657,2639,0);
 private final Player player;private final List<PestNpc> portals=new ArrayList<>(),enemies=new ArrayList<>();private PestNpc knight;private boolean finished;private int ticks;
 private SoloPest(Player p){super(InstanceConfiguration.CLOSE_ON_EMPTY,PestControl.GAME_BOUNDARY);player=p;}
 public static boolean enter(Player p){if(!Boolean.getBoolean("solo.mode")||!p.getUtilityMagic().canInteract()||p.getInstance()!=null)return false;if(p.combatLevel<40){p.sendMessage("Você precisa de nível de combate 40 para Pest Control.");return false;}SoloPest a=new SoloPest(p);a.add(p);p.moveTo(new Position(2656,2592,a.getHeight()));a.knight=a.new PestNpc(1756,2656,2592,250,-1);int[][] data={{1739,2628,2591},{1740,2680,2588},{1741,2669,2570},{1742,2645,2569}};for(int i=0;i<4;i++)a.portals.add(a.new PestNpc(data[i][0],data[i][1],data[i][2],200,i));a.loop();p.sendMessage("Pest Control solo: destrua os 4 portais e defenda Void Knight. Vitória: 5 pontos e 25.000 coins. Limite: 10 minutos.");return true;}
 public static void crossGate(Player p,int x,int y){if(!(p.getInstance() instanceof SoloPest)||Math.abs(p.absX-x)>2||Math.abs(p.absY-y)>2)return;int tx=p.absX,ty=p.absY;if(x==2643||x==2670)tx=p.absX<=x?x+1:x;else ty=p.absY<=y?y+1:y;p.getPA().movePlayer(tx,ty,p.heightLevel);}
 private boolean active(){return !finished&&!isDisposed()&&player.getInstance()==this&&!player.isDead&&!player.isDisconnected()&&player.getHealth().getCurrentHealth()>0;}
 private void loop(){CycleEventHandler.getSingleton().addEvent(this,new CycleEvent(){public void execute(CycleEventContainer e){if(!active()){e.stop();return;}ticks++;if(knight.isDead()||knight.getHealth().getCurrentHealth()<=0||ticks>=1000){finish(false);e.stop();return;}if(ticks%50==1){for(PestNpc portal:portals)if(!portal.isDead()&&!portal.isUnregister()){PestNpc n=new PestNpc(1693,portal.absX+2,portal.absY+2,35,4);enemies.add(n);}}if(ticks%5==0){for(PestNpc n:enemies)if(!n.isDead()&&!n.isUnregister()){NPCDumbPathFinder.walkTowards(n,knight.absX,knight.absY);if(n.getDistance(knight.absX,knight.absY)<=3)knight.appendDamage(n,2,Hitmark.HIT);}}if(ticks%100==0)player.sendMessage("Pest Control: "+portals.stream().filter(n->!n.isDead()).count()+" portais; Void Knight: "+knight.getHealth().getCurrentHealth()+" HP.");}},1);}
 private void finish(boolean won){if(!active())return;finished=true;if(won){player.pcPoints=Math.min(Integer.MAX_VALUE-5,player.pcPoints)+5;SoloActivityRewards.give(player,List.of(new GameItem(995,25000)),EXIT);player.getQuestTab().updateInformationTab();}remove(player);player.moveTo(EXIT);player.sendMessage(won?"Vitória! +5 pontos de Pest Control. Pontos e recompensa salvos.":"Pest Control encerrado sem recompensa. Seus equipamentos foram preservados.");PlayerSave.saveGame(player);}
 @Override public boolean handleDeath(Player p){if(p!=player)return false;p.getHealth().reset();p.isDead=false;finish(false);return true;}
 @Override public void onDispose(){CycleEventHandler.getSingleton().stopEvents(this);}
 public final class PestNpc extends NPC {private final int role;private boolean credited;PestNpc(int id,int x,int y,int hp,int role){super(id,new Position(x,y,SoloPest.this.getHeight()));this.role=role;spawnedBy=player.getIndex();SoloPest.this.add(this);setDefaultNpcStats(NPCSpawning.getStats(hp,70,40));getBehaviour().setRespawn(false);getBehaviour().setWalkHome(false);walkingType=role==4?1:-1;if(role==4){getBehaviour().setAggressive(true);setNpcAutoAttacks(List.of(new NPCAutoAttackBuilder().setAnimation(new Animation(390)).setCombatType(CombatType.MELEE).setDistanceRequiredForAttack(1).setAttackDelay(5).setMaxHit(6).setHitDelay(1).createNPCAutoAttack()));}}
 @Override public boolean canBeDamaged(Entity e){return active()&&!isDead()&&(role==-1?e instanceof PestNpc&&((PestNpc)e).role==4:e==player);}
 @Override public boolean canBeAttacked(Entity e){return canBeDamaged(e);}
 @Override public void onDeath(){if(!active()||credited||!isDead())return;credited=true;if(role>=0&&role<4&&portals.stream().allMatch(n->n.isDead()))finish(true);else if(role==-1)finish(false);}
 }
}
